                      <h4 className="text-sm font-black text-slate-900 uppercase">{r.fullName}</h4>
                      <p className="text-[10px] text-slate-400 font-mono mt-0.5">NIK: {r.nik}</p>
                    </div>
                    <div className="text-[9px] font-black text-slate-400 uppercase bg-white px-2 py-1 rounded-lg border border-slate-200">
                      {r.dusun}
                    </div>
                 </div>
               </button>
             )) : (
               <div className="py-10 text-center">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Pencarian Ibu Penduduk Aktif...</p>
               </div>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

