import React, { useState, useMemo } from 'react';
import { 
  Search, 
  HeartPulse, 
  Plus, 
  MapPin, 
  Info, 
  X, 
  Save, 
  // Add User import to fix the "Cannot find name 'User'" error
  User,
  Users,
  FileText, 
  Eye, 
  Calendar, 
  Clock, 
  Download, 
  Printer,
  ChevronRight,
  Filter,
  Baby,
  Stethoscope
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { Resident, ResidentStatus, AppConfig } from '../types';
import { calculatePregnancyAge, formatDate, calculateAge } from '../utils/helpers';
import EditResidentModal from './EditResidentModal';

interface PregnancyManagementProps {
  residents: Resident[];
  setResidents: React.Dispatch<React.SetStateAction<Resident[]>>;
}

const PregnancyManagement: React.FC<PregnancyManagementProps> = ({ residents, setResidents }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [dusunFilter, setDusunFilter] = useState('');
  const [isSelectingResident, setIsSelectingResident] = useState(false);
  const [editingResident, setEditingResident] = useState<Resident | null>(null);

  const dusunList = useMemo(() => 
    Array.from(new Set(residents.filter(r => r.status === 'Aktif').map(r => r.dusun))).sort()
  , [residents]);

  const pregnantResidents = useMemo(() => {
    return residents
      .filter(r => r.status === 'Aktif' && r.isPregnant)
      .filter(r => !dusunFilter || r.dusun === dusunFilter)
      .filter(r => 
        r.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
        r.nik.includes(searchTerm) ||
        r.noKK.includes(searchTerm)
      )
      .sort((a, b) => new Date(a.pregnancyStartDate!).getTime() - new Date(b.pregnancyStartDate!).getTime());
  }, [residents, dusunFilter, searchTerm]);

  const handleMarkNotPregnant = (resident: Resident) => {
    if (window.confirm(`Hapus status hamil untuk ${resident.fullName}?`)) {
      setResidents(prev => prev.map(r => 
        r.id === resident.id ? { ...r, isPregnant: false, pregnancyStartDate: undefined } : r
      ));
    }
  };

  const handleExportPDF = () => {
    if (pregnantResidents.length === 0) return alert("Tidak ada data untuk diekspor.");

    const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });

    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text('PEMERINTAH KABUPATEN BLORA', 148.5, 15, { align: 'center' });
    doc.setFontSize(12);
    doc.text('KECAMATAN TODANAN - DESA NGUMBUL', 148.5, 21, { align: 'center' });
    doc.setFontSize(11);
    doc.text('DAFTAR MONITORING IBU HAMIL (KIA)', 148.5, 30, { align: 'center' });
    doc.setLineWidth(0.5);
    doc.line(20, 32, 277, 32);

    const tableData = pregnantResidents.map((p, idx) => {
      const age = calculatePregnancyAge(p.pregnancyStartDate!);
      return [
        idx + 1,
        p.fullName.toUpperCase(),
        p.nik,
        p.noKK,
        formatDate(p.pregnancyStartDate!),
        `${age.weeks} Minggu, ${age.days} Hari`,
        p.dusun.toUpperCase(),
        `RT ${p.rt}/RW ${p.rw}`
      ];
    });

    autoTable(doc, {
      head: [['NO', 'NAMA IBU', 'NIK', 'NOMOR KK', 'TGL MULAI HAMIL', 'USIA KEHAMILAN', 'DUSUN', 'ALAMAT']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 8, cellPadding: 2 },
      headStyles: { fillColor: [219, 39, 119], halign: 'center' },
    });

    doc.save(`Data_IbuHamil_Ngumbul_${new Date().toISOString().split('T')[0]}.pdf`);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Header & Main Actions */}
      <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-200">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
          <div className="flex items-center space-x-6">
            <div className="w-14 h-14 bg-pink-500 text-white rounded-2xl flex items-center justify-center shadow-lg shadow-pink-500/20">
              <HeartPulse size={32} />
            </div>
            <div>
              <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter leading-none">Manajemen Kehamilan</h2>
              <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mt-2">Monitoring Ibu Hamil & Kesehatan Ibu Anak (KIA)</p>
            </div>
          </div>

          <div className="flex items-center flex-wrap gap-3">
             <button 
              onClick={() => setIsSelectingResident(true)}
              className="flex items-center space-x-3 px-8 py-4 bg-slate-900 text-white rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-pink-600 transition-all shadow-xl shadow-slate-200"
            >
              <Plus size={18} />
              <span>Input Data Bumil</span>
            </button>
            <button 
              onClick={handleExportPDF}
              className="flex items-center space-x-2 px-6 py-4 bg-white border border-slate-200 text-slate-700 rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-slate-50 transition-all"
            >
              <Download size={18} />
              <span>Ekspor PDF</span>
            </button>
          </div>
        </div>
      </div>

      {/* Filter & Search Bar */}
      <div className="flex flex-col md:flex-row items-center gap-4 bg-white p-4 rounded-[2rem] border border-slate-200 shadow-sm">
        <div className="flex-1 flex items-center bg-slate-50 rounded-2xl px-5 py-3 border border-slate-100 w-full focus-within:bg-white focus-within:ring-4 focus-within:ring-pink-500/10 transition-all">
          <Search size={18} className="text-slate-400 mr-3" />
          <input 
            type="text" 
            placeholder="Cari Nama Ibu / NIK / No. KK..."
            className="bg-transparent border-none outline-none text-sm w-full font-bold"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex items-center bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 min-w-[200px] w-full md:w-auto">
           <MapPin size={16} className="text-slate-400 mr-2" />
           <select 
             className="bg-transparent text-xs font-black uppercase outline-none w-full"
             value={dusunFilter}
             onChange={(e) => setDusunFilter(e.target.value)}
           >
             <option value="">Semua Dusun</option>
             {dusunList.map(d => <option key={d} value={d}>{d}</option>)}
           </select>
        </div>
      </div>

      {/* Pregnant Residents List */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {pregnantResidents.length > 0 ? pregnantResidents.map((p) => {
          const pregAge = calculatePregnancyAge(p.pregnancyStartDate!);
          return (
            <div key={p.id} className="bg-white rounded-[2rem] border border-slate-100 shadow-sm hover:border-pink-500 transition-all group p-6 overflow-hidden relative">
               <div className="absolute top-0 right-0 w-32 h-32 bg-pink-50 rounded-full -mr-16 -mt-16 opacity-50 group-hover:scale-110 transition-transform"></div>

               <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center space-x-3">
                     <div className="w-12 h-12 bg-pink-100 text-pink-600 rounded-2xl flex items-center justify-center">
                        <User size={24} />
                     </div>
                     <div>
                        <h4 className="text-sm font-black text-slate-900 uppercase leading-none truncate max-w-[150px]">{p.fullName}</h4>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">NIK: {p.nik}</p>
                     </div>
                  </div>
                  <div className="p-2 bg-slate-50 rounded-xl group-hover:bg-pink-600 group-hover:text-white transition-all cursor-pointer" onClick={() => setEditingResident(p)}>
                     <Eye size={16} />
                  </div>
               </div>

               <div className="space-y-4 relative z-10">
                  <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                     <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Usia Kehamilan</p>
                     <p className="text-lg font-black text-pink-600 leading-none">
                        {pregAge.weeks} <span className="text-xs font-bold text-slate-400">Minggu</span>, {pregAge.days} <span className="text-xs font-bold text-slate-400">Hari</span>
                     </p>
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                     <div className="bg-white border border-slate-100 p-3 rounded-xl">
                        <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5">Mulai Hamil</p>
                        <p className="text-[10px] font-black text-slate-700">{formatDate(p.pregnancyStartDate!)}</p>
                     </div>
                     <div className="bg-white border border-slate-100 p-3 rounded-xl">
                        <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5">Dusun</p>
                        <p className="text-[10px] font-black text-slate-700 uppercase">{p.dusun}</p>
                     </div>
                  </div>

                  <button 
                    onClick={() => handleMarkNotPregnant(p)}
                    className="w-full py-3 bg-white border border-slate-200 text-slate-400 hover:text-rose-600 hover:border-rose-200 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center justify-center space-x-2"
                  >
                    <Stethoscope size={14} />
                    <span>Sudah Melahirkan / Berakhir</span>
                  </button>
               </div>
            </div>
          );
        }) : (
          <div className="col-span-full py-32 bg-white rounded-[3rem] border border-dashed border-slate-200 text-center">
             <HeartPulse size={48} className="mx-auto text-slate-200 mb-4" />
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Tidak ada data ibu hamil aktif ditemukan.</p>
          </div>
        )}
      </div>

      {/* Select Resident Modal */}
      {isSelectingResident && (
        <SelectFemaleResidentModal 
          residents={residents} 
          onClose={() => setIsSelectingResident(false)}
          onSelect={(r) => {
            setEditingResident(r);
            setIsSelectingResident(false);
          }}
        />
      )}

      {/* Edit Modal (used for both marking and updating) */}
      {editingResident && (
        <EditResidentModal 
          resident={editingResident} 
          onClose={() => setEditingResident(null)} 
          onSave={(updated) => {
            setResidents(prev => prev.map(r => r.id === updated.id ? updated : r));
            setEditingResident(null);
          }}
        />
      )}
    </div>
  );
};

const SelectFemaleResidentModal: React.FC<{ residents: Resident[], onClose: () => void, onSelect: (r: Resident) => void }> = ({ residents, onClose, onSelect }) => {
  const [query, setQuery] = useState('');

  const filtered = useMemo(() => {
    return residents
      .filter(r => r.status === 'Aktif' && r.gender.includes('Perempuan') && !r.isPregnant && calculateAge(r.birthDate) >= 15)
      .filter(r => 
        r.fullName.toLowerCase().includes(query.toLowerCase()) || 
        r.nik.includes(query)
      ).slice(0, 5);
  }, [residents, query]);

  return (
