                        <p className="text-[10px] font-black text-slate-700">{formatDate(p.pregnancyStartDate!)}</p>
                     </div>
                     <div className="bg-white border border-slate-100 p-3 rounded-xl">
                        <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5">Dusun</p>
