import React, { useState } from 'react';
import { X, User, Printer, UserPlus, Skull, Trash2, Calendar, Users, Save, PlaneLanding, HeartPulse, ShieldAlert, ShieldCheck, Stethoscope } from 'lucide-react';
import { Resident, ResidentStatus, PregnancyRisk } from '../types';
import { calculateAge } from '../utils/helpers';
import EditResidentModal from './EditResidentModal';

interface FamilyDetailModalProps {
  noKK: string;
  residents: Resident[];
  setResidents: React.Dispatch<React.SetStateAction<Resident[]>>;
  onClose: () => void;
}

const FamilyDetailModal: React.FC<FamilyDetailModalProps> = ({ noKK, residents, setResidents, onClose }) => {
  const [editingMember, setEditingMember] = useState<Resident | null>(null);
  const [isAddingMember, setIsAddingMember] = useState(false);
  const [deathConfirm, setDeathConfirm] = useState<Resident | null>(null);
  const [deletingMember, setDeletingMember] = useState<Resident | null>(null);
  const [pregnancyConfirm, setPregnancyConfirm] = useState<Resident | null>(null);

  const targetNoKK = noKK.trim();
  const headRef = residents.find(r => r.noKK.trim() === targetNoKK && r.isHeadOfFamily);
  const currentViewStatus = headRef?.status || 'Aktif';

  const familyMembers = residents.filter(r => r.noKK.trim() === targetNoKK && r.status === currentViewStatus);
  const headOfFamily = familyMembers.find(r => r.isHeadOfFamily) || familyMembers[0];

  const finalizeDeleteMember = (reason: string) => {
    if (!deletingMember) return;
    setResidents(prev => {
      const updated = prev.map(r => {
        if (r.id === deletingMember.id) {
          return { 
            ...r, 
            status: 'Terhapus' as ResidentStatus, 
            deleteDate: new Date().toISOString().split('T')[0],
            deleteReason: reason
          };
        }
        return r;
      });

      const remainingInKK = updated.filter(r => r.noKK.trim() === targetNoKK && r.status === currentViewStatus);
      if (remainingInKK.length === 0) onClose();

      return updated;
    });
    setDeletingMember(null);
  };

  const archiveDeath = (date: string) => {
    if (!deathConfirm) return;
    setResidents(prev => prev.map(r => 
      r.id === deathConfirm.id ? { ...r, status: 'Meninggal' as ResidentStatus, deathDate: date, isPregnant: false, pregnancyRisk: undefined } : r
    ));
    setDeathConfirm(null);
  };

  const handleArchivePregnancy = (date: string, risk: PregnancyRisk) => {
    if (!pregnancyConfirm) return;
    setResidents(prev => prev.map(r => 
      r.id === pregnancyConfirm.id ? { ...r, isPregnant: true, pregnancyStartDate: date, pregnancyRisk: risk } : r
    ));
    setPregnancyConfirm(null);
  };

  const handleUpdateMember = (updated: Resident) => {
    setResidents(prev => prev.map(r => r.id === updated.id ? updated : r));
    setEditingMember(null);
  };

  const handleAddMember = (newMember: Resident) => {
    setResidents(prev => [...prev, { ...newMember, status: 'Aktif' as ResidentStatus }]);
    setIsAddingMember(false);
  };

  const inputClass = "w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 text-sm font-bold text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-blue-500/20 transition-all";

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl w-full max-w-6xl max-h-[92vh] overflow-hidden flex flex-col border border-slate-200 dark:border-slate-800 animate-in zoom-in-95">

        {/* Header Modal */}
        <div className="p-8 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between no-print bg-white dark:bg-slate-900">
          <div className="flex items-center space-x-6">
            <div className={`w-14 h-14 ${currentViewStatus === 'Pindah' ? 'bg-amber-500' : currentViewStatus === 'Terhapus' ? 'bg-slate-700' : 'bg-slate-900'} rounded-2xl flex items-center justify-center text-white shadow-xl`}>
              <User size={28} />
            </div>
            <div>
              <h3 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tighter leading-none">
                {currentViewStatus === 'Pindah' ? 'Rincian Keluarga (Pindah)' : currentViewStatus === 'Terhapus' ? 'Rincian Keluarga (Terhapus)' : 'Daftar Anggota Keluarga'}
              </h3>
              <p className="text-slate-400 text-[10px] font-bold font-mono tracking-widest mt-2 uppercase">NO. KK: {noKK}</p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            {currentViewStatus === 'Aktif' && (
              <button onClick={() => setIsAddingMember(true)} className="flex items-center space-x-2 px-6 py-3 bg-emerald-600 text-white rounded-2xl text-[10px] font-black hover:bg-emerald-700 transition-all uppercase tracking-widest shadow-lg shadow-emerald-200">
                <UserPlus size={16} />
                <span>Tambah Anggota</span>
              </button>
            )}
            <button onClick={() => window.print()} className="p-3 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-2xl transition-all" title="Cetak Data"><Printer size={20} /></button>
            <button onClick={onClose} className="p-3 bg-slate-100 dark:bg-slate-800 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/30 rounded-2xl transition-all"><X size={24} /></button>
          </div>
        </div>

        {/* List Anggota */}
        <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-slate-50/20 dark:bg-slate-900/50">
          <div className="grid grid-cols-1 gap-4">
            {familyMembers.length > 0 ? familyMembers.sort((a,b) => (a.isHeadOfFamily ? -1 : 1)).map((m) => {
              const isFemale = m.gender.includes('Perempuan');
              return (
                <div key={m.id} className="bg-white dark:bg-slate-800 p-3 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm flex flex-col md:flex-row md:items-center hover:border-blue-200 dark:hover:border-blue-800 transition-all group">
                  <div className={`px-6 py-4 md:w-48 text-center md:text-left rounded-2xl md:mr-6 font-black text-[10px] uppercase tracking-widest shadow-sm ${
                    m.isHeadOfFamily 
                      ? (currentViewStatus === 'Pindah' ? 'bg-amber-500 text-white' : currentViewStatus === 'Terhapus' ? 'bg-slate-700 text-white' : 'bg-slate-900 dark:bg-blue-600 text-white') 
                      : 'bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300'
                  }`}>
                    {m.relationship.includes('. ') ? m.relationship.split('. ')[1] : m.relationship}
                  </div>

                  <div className="flex-1 p-2 grid grid-cols-2 md:grid-cols-4 gap-4 items-center">
                    <div>
                      <button onClick={() => currentViewStatus === 'Aktif' && setEditingMember(m)} className={`text-xs font-black font-mono ${currentViewStatus === 'Aktif' ? 'text-blue-600 dark:text-blue-400 hover:underline' : 'text-slate-400'}`}>{m.nik}</button>
                      <h5 className="text-sm font-black text-slate-900 dark:text-white uppercase truncate mt-0.5">{m.fullName}</h5>
                      {m.isPregnant && (
                        <span className={`inline-flex items-center px-2 py-0.5 rounded text-[8px] font-black uppercase mt-1 animate-pulse ${
                          m.pregnancyRisk === 'Tinggi' ? 'bg-rose-100 text-rose-700' :
                          m.pregnancyRisk === 'Sedang' ? 'bg-amber-100 text-amber-700' :
                          'bg-emerald-100 text-emerald-700'
                        }`}>
                          <HeartPulse size={8} className="mr-1" /> Hamil ({m.pregnancyRisk || 'Resiko ?'})
                        </span>
                      )}
                    </div>
                    <div className="text-center md:text-left">
                      <p className="text-[8px] text-slate-400 font-black uppercase mb-0.5">L/P</p>
                      <span className="text-xs font-bold text-slate-600 dark:text-slate-400 uppercase">{m.gender.includes('Laki') ? 'Laki-laki' : 'Perempuan'}</span>
                    </div>
                    <div className="text-center md:text-left">
                      <p className="text-[8px] text-slate-400 font-black uppercase mb-0.5">Usia</p>
                      <p className="text-sm font-black text-slate-900 dark:text-white">{calculateAge(m.birthDate)} <span className="text-[10px] font-normal text-slate-400 uppercase tracking-tighter">Tahun</span></p>
                    </div>
                    <div className="flex justify-end space-x-2">
                      {currentViewStatus === 'Aktif' && (
                        <>
                          {isFemale && !m.isPregnant && (
                            <button onClick={() => setPregnancyConfirm(m)} className="p-2.5 bg-pink-50 dark:bg-pink-900/30 text-pink-500 rounded-xl hover:bg-pink-500 hover:text-white transition-all shadow-sm" title="Lapor Hamil">
                              <HeartPulse size={16} />
                            </button>
                          )}
                          <button onClick={() => setDeathConfirm(m)} className="p-2.5 bg-slate-50 dark:bg-slate-700 text-slate-400 dark:text-slate-300 rounded-xl hover:bg-slate-900 dark:hover:bg-slate-600 hover:text-white transition-all shadow-sm" title="Lapor Kematian"><Skull size={16} /></button>
                          <button onClick={() => setDeletingMember(m)} className="p-2.5 bg-rose-50 dark:bg-rose-900/30 text-rose-400 rounded-xl hover:bg-rose-600 hover:text-white transition-all shadow-sm" title="Pindahkan ke Terhapus"><Trash2 size={16} /></button>
                        </>
                      )}
                    </div>
                  </div>
                </div>
              );
            }) : (
              <div className="text-center py-24 bg-white dark:bg-slate-800 rounded-[3rem] border border-dashed border-slate-200 dark:border-slate-700">
                <Users size={48} className="mx-auto text-slate-200 dark:text-slate-700 mb-4" />
                <p className="text-slate-400 font-black uppercase text-xs tracking-[0.2em]">Tidak ada anggota keluarga aktif ditemukan.</p>
              </div>
            )}
          </div>
        </div>

        <div className="p-8 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 flex justify-between items-center no-print">
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest italic">Data dipindahkan ke arsip sesuai jenis peristiwa (Meninggal/Terhapus).</p>
          <button onClick={onClose} className={`px-12 py-4 ${currentViewStatus === 'Pindah' ? 'bg-amber-500' : currentViewStatus === 'Terhapus' ? 'bg-slate-700' : 'bg-slate-900 dark:bg-blue-600'} text-white rounded-[1.5rem] text-sm font-black hover:opacity-90 shadow-xl transition-all uppercase tracking-widest`}>Tutup Dialog</button>
        </div>

        {editingMember && <EditResidentModal resident={editingMember} onClose={() => setEditingMember(null)} onSave={handleUpdateMember} />}
        {isAddingMember && <InternalAddMemberModal noKK={noKK} familyBase={headOfFamily} onClose={() => setIsAddingMember(false)} onSave={handleAddMember} />}
        {deathConfirm && <DeathModal member={deathConfirm} onClose={() => setDeathConfirm(null)} onConfirm={archiveDeath} />}
        {deletingMember && <MemberDeleteReasonModal member={deletingMember} onClose={() => setDeletingMember(null)} onConfirm={finalizeDeleteMember} />}
        {pregnancyConfirm && <PregnancyModal member={pregnancyConfirm} onClose={() => setPregnancyConfirm(null)} onConfirm={handleArchivePregnancy} />}
      </div>
    </div>
  );
};

