export default App;

import React, { useState, useEffect, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import PopulationManagement from './components/PopulationManagement';
import RecapIndicators from './components/RecapIndicators';
import AppSettings from './components/AppSettings';
import ArchivedResidents from './components/ArchivedResidents';
import BirthManagement from './components/BirthManagement';
import PregnancyManagement from './components/PregnancyManagement';
import AdvancedSearch from './components/AdvancedSearch';
import { Resident, AppConfig } from './types';
import { initialResidents } from './mockData';
import { initializeApp, getApp, getApps } from 'firebase/app';
import { getFirestore, doc, setDoc, getDoc, onSnapshot } from 'firebase/firestore';

const App: React.FC = () => {
  const [residents, setResidents] = useState<Resident[]>(() => {
    const saved = localStorage.getItem('siga_residents');
    return saved ? JSON.parse(saved) : [];
  });

  const [config, setConfig] = useState<AppConfig>(() => {
    const saved = localStorage.getItem('siga_config');
    return saved ? JSON.parse(saved) : {
      appName: 'SIGA Ngumbul',
      subtitle: 'Kec. Todanan, Kab. Blora',
      logoUrl: 'https://upload.wikimedia.org/wikipedia/commons/1/1d/Lambang_Kabupaten_Blora.png',
      operatorName: 'ADMIN DESA',
      villageHeadName: 'SULARNO',
      theme: 'light',
      firebaseConfig: { enabled: false }
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSyncing, setIsSyncing] = useState(false);

  const isHydrated = useRef(false); 
  const isInternalUpdate = useRef(false);
  const lastUpdateToken = useRef<string | null>(null);

  useEffect(() => {
    const root = window.document.documentElement;
    if (config.theme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
  }, [config.theme]);

  // 1. Firebase Listener (DOWNLOAD)
  useEffect(() => {
    if (!config.firebaseConfig?.enabled || !config.firebaseConfig.projectId) {
      isHydrated.current = true;
      return;
    }

    let unsubRes = () => {};
    try {
      const firebaseApp = getApps().length === 0 ? initializeApp(config.firebaseConfig) : getApp();
      const db = getFirestore(firebaseApp);

      unsubRes = onSnapshot(doc(db, "ngumbul_data", "residents_master"), (snap) => {
        if (snap.metadata.hasPendingWrites) return;

        if (snap.exists()) {
          const cloudData = snap.data();
          // Jika data di cloud ada isinya, dan berbeda dengan lokal
          if (cloudData.lastUpdated !== lastUpdateToken.current) {
            lastUpdateToken.current = cloudData.lastUpdated;
            const cloudList = cloudData.list || [];

            // ANTI-WIPE: Hanya timpa lokal jika cloud benar-benar punya data atau memang kita mau kosongkan
            // Tapi jika cloud kosong dan lokal ada isinya (kasus browser baru), 
            // kita jangan set isHydrated dulu sampai kita putuskan siapa yang menang.
            isInternalUpdate.current = true;
            setResidents(cloudList);
            localStorage.setItem('siga_residents', JSON.stringify(cloudList));
          }
        }
        isHydrated.current = true;
      }, (err) => {
        console.error("Firebase Sync Error:", err);
        isHydrated.current = true;
      });
    } catch (e) {
      isHydrated.current = true;
    }
    return () => unsubRes();
  }, [config.firebaseConfig?.enabled, config.firebaseConfig?.projectId]);

  // 2. Firebase Sync (UPLOAD)
  useEffect(() => {
    localStorage.setItem('siga_residents', JSON.stringify(residents));

    if (!isHydrated.current) return;
    if (isInternalUpdate.current) {
      isInternalUpdate.current = false;
      return;
    }

    if (config.firebaseConfig?.enabled && config.firebaseConfig.projectId) {
      // JANGAN upload data kosong jika kita baru saja buka aplikasi (proteksi browser baru)
      if (residents.length === 0 && !lastUpdateToken.current) return;

      const timer = setTimeout(async () => {
        setIsSyncing(true);
        try {
          const db = getFirestore(getApp());
          const now = new Date().toISOString();
          lastUpdateToken.current = now;
          await setDoc(doc(db, "ngumbul_data", "residents_master"), { 
            list: residents,
            lastUpdated: now
          });
        } catch (e) {
          console.error(e);
        } finally {
          setIsSyncing(false);
        }
      }, 3000); 
      return () => clearTimeout(timer);
    }
  }, [residents]);

  // Manual Cloud Actions
  const forcePush = async () => {
    if (!config.firebaseConfig?.enabled) return;
    setIsSyncing(true);
    try {
      const db = getFirestore(getApp());
      const now = new Date().toISOString();
      lastUpdateToken.current = now;
      await setDoc(doc(db, "ngumbul_data", "residents_master"), { list: residents, lastUpdated: now });
      alert("Berhasil mengunggah data lokal ke Cloud.");
    } catch (e) { alert("Gagal unggah: " + e); }
    finally { setIsSyncing(false); }
  };

  const forcePull = async () => {
    if (!config.firebaseConfig?.enabled) return;
    setIsSyncing(true);
    try {
      const db = getFirestore(getApp());
      const snap = await getDoc(doc(db, "ngumbul_data", "residents_master"));
      if (snap.exists()) {
        const data = snap.data();
        setResidents(data.list || []);
        alert("Berhasil mengambil data dari Cloud.");
      } else { alert("Data di Cloud kosong."); }
    } catch (e) { alert("Gagal ambil data: " + e); }
    finally { setIsSyncing(false); }
  };

  const renderContent = () => {
    const activeResidents = residents.filter(r => r.status === 'Aktif');
    switch (activeTab) {
      case 'dashboard': return <Dashboard residents={activeResidents} />;
      case 'penduduk': return <PopulationManagement residents={residents} setResidents={setResidents} config={config} />;
      case 'pencarian': return <AdvancedSearch residents={activeResidents} setResidents={setResidents} config={config} />;
      case 'kelahiran': return <BirthManagement residents={residents} setResidents={setResidents} />;
      case 'kehamilan': return <PregnancyManagement residents={residents} setResidents={setResidents} />;
      case 'arsip': return <ArchivedResidents residents={residents} setResidents={setResidents} />;
      case 'rekap': return <RecapIndicators residents={activeResidents} config={config} />;
      case 'profil': return <AppSettings config={config} setConfig={setConfig} onForcePush={forcePush} onForcePull={forcePull} />;
      default: return <Dashboard residents={activeResidents} />;
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} config={config} setConfig={setConfig} isSyncing={isSyncing}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Save, Globe, RefreshCcw, User, Shield, Image as ImageIcon, Cloud, Database, Wifi, WifiOff, UploadCloud, DownloadCloud } from 'lucide-react';
import { AppConfig } from '../types';

interface AppSettingsProps {
  config: AppConfig;
  setConfig: React.Dispatch<React.SetStateAction<AppConfig>>;
  onForcePush: () => void;
  onForcePull: () => void;
}

const AppSettings: React.FC<AppSettingsProps> = ({ config, setConfig, onForcePush, onForcePull }) => {
  const [formData, setFormData] = useState<AppConfig>(config);
  const [isSaved, setIsSaved] = useState(false);

  useEffect(() => {
    setFormData(config);
  }, [config]);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    setConfig(formData);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 3000);
  };

  const updateFirebase = (field: string, value: any) => {
    setFormData(prev => ({
      ...prev,
      firebaseConfig: {
        ...(prev.firebaseConfig || {
          apiKey: '',
          authDomain: '',
          projectId: '',
          storageBucket: '',
          messagingSenderId: '',
          appId: '',
          enabled: false
        }),
        [field]: value
      }
    }));
  };

  return (
    <div className="max-w-4xl mx-auto grid grid-cols-1 lg:grid-cols-2 gap-6 pb-20">
      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm h-fit">
        <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
          <h2 className="text-sm font-black uppercase tracking-widest text-slate-900 dark:text-white">Profil Aplikasi & Desa</h2>
          <Globe size={18} className="text-blue-600" />
        </div>

        <form onSubmit={handleSave} className="p-8 space-y-6">
          <div className="space-y-4">
            <div>
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1.5">Nama Aplikasi</label>
              <input type="text" className="w-full bg-slate-50 dark:bg-slate-800 dark:text-white border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 font-black text-xs uppercase" value={formData.appName} onChange={(e) => setFormData({...formData, appName: e.target.value})} />
            </div>
            <div>
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1.5">Nama Kepala Desa (TTD PDF)</label>
              <input type="text" className="w-full bg-slate-50 dark:bg-slate-800 dark:text-white border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 font-black text-xs uppercase" value={formData.villageHeadName} onChange={(e) => setFormData({...formData, villageHeadName: e.target.value})} />
            </div>
            <div>
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1.5">Nama Operator</label>
              <input type="text" className="w-full bg-slate-50 dark:bg-slate-800 dark:text-white border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 font-black text-xs uppercase" value={formData.operatorName} onChange={(e) => setFormData({...formData, operatorName: e.target.value})} />
            </div>
          </div>

          <button type="submit" className="w-full py-4 bg-slate-900 dark:bg-blue-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl flex items-center justify-center space-x-2 transition-all hover:bg-blue-600">
            <Save size={16} />
            <span>Simpan Perubahan</span>
          </button>
        </form>
      </div>

      <div className="bg-slate-950 rounded-[2.5rem] border border-slate-800 overflow-hidden shadow-2xl text-white">
        <div className="p-6 border-b border-white/10 flex items-center justify-between">
          <div className="flex items-center space-x-3">
             <Cloud size={18} className="text-emerald-400" />
             <h2 className="text-sm font-black uppercase tracking-widest">Firebase Cloud Control</h2>
          </div>
          <button 
             onClick={() => updateFirebase('enabled', !formData.firebaseConfig?.enabled)}
             className={`w-12 h-6 rounded-full transition-all relative ${formData.firebaseConfig?.enabled ? 'bg-emerald-500' : 'bg-slate-700'}`}
          >
             <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all shadow-md ${formData.firebaseConfig?.enabled ? 'left-7' : 'left-1'}`}></div>
          </button>
        </div>

        <div className="p-8 space-y-5">
           <div className="grid grid-cols-2 gap-3 mb-4">
              <button onClick={onForcePush} className="flex flex-col items-center justify-center p-4 bg-white/5 border border-white/10 rounded-2xl hover:bg-white/10 transition-all group">
                 <UploadCloud size={24} className="text-blue-400 mb-2 group-hover:scale-110 transition-transform" />
                 <span className="text-[8px] font-black uppercase tracking-widest">Unggah Paksa</span>
              </button>
              <button onClick={onForcePull} className="flex flex-col items-center justify-center p-4 bg-white/5 border border-white/10 rounded-2xl hover:bg-white/10 transition-all group">
                 <DownloadCloud size={24} className="text-emerald-400 mb-2 group-hover:scale-110 transition-transform" />
                 <span className="text-[8px] font-black uppercase tracking-widest">Ambil Paksa</span>
              </button>
           </div>

           <div className="space-y-4">
              <div>
                <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest block mb-1">Project ID</label>
                <input type="text" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-xs font-mono focus:bg-white/10 outline-none" value={formData.firebaseConfig?.projectId || ''} onChange={(e) => updateFirebase('projectId', e.target.value)} />
              </div>
              <div>
                <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest block mb-1">API Key</label>
                <input type="password" name="apiKey" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-xs font-mono focus:bg-white/10 outline-none" value={formData.firebaseConfig?.apiKey || ''} onChange={(e) => updateFirebase('apiKey', e.target.value)} />
              </div>
           </div>

           <button onClick={handleSave} className="w-full py-4 bg-blue-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl transition-all flex items-center justify-center space-x-2">
             <RefreshCcw size={16} />
             <span>Terapkan Konfigurasi</span>
           </button>
        </div>
      </div>
    </div>
  );
};

export default AppSettings;

