                   <div className="min-w-0">
                      <h4 className="text-[13px] font-black uppercase text-slate-900 dark:text-white leading-tight truncate">{r.fullName}</h4>
                      <p className="text-[10px] font-mono text-slate-400 mt-0.5 truncate">NIK: {r.nik}</p>
