                         <span className="text-[10px] font-black text-slate-700 dark:text-slate-300">
                           {formatDate(subTab === 'Meninggal' ? r.deathDate! : subTab === 'Pindah' ? r.moveDate! : r.deleteDate!)}
                         </span>
                      </div>
                   </div>
                   <div>
                      <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5 tracking-widest">Status Hubungan</p>
                      <p className="text-[10px] font-bold text-slate-600 dark:text-slate-400 uppercase">{r.relationship.includes('. ') ? r.relationship.split('. ')[1] : r.relationship}</p>
                   </div>
                </div>

                <div className="bg-slate-50 dark:bg-slate-800/50 p-3 rounded-xl border border-dashed border-slate-200 dark:border-slate-700">
                   <p className="text-[8px] font-black text-slate-400 uppercase mb-1 tracking-widest">Keterangan / Alasan</p>
                   <div className="flex items-start space-x-2">
                      <MessageSquare size={12} className="text-slate-300 mt-0.5 shrink-0" />
