             <div className="flex items-center gap-2 pt-2 border-t border-slate-50 dark:border-slate-800">
                {(subTab === 'Pindah' || subTab === 'Terhapus') && (
                  <button onClick={() => setViewingFamilyKK(r.noKK)} className="flex-1 py-2.5 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 rounded-xl text-[9px] font-black uppercase flex items-center justify-center space-x-2">
                     <Eye size={12} /> <span>Anggota</span>
