                <button onClick={() => restoreData(r)} className="flex-1 py-2.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-xl text-[9px] font-black uppercase border border-blue-100 dark:border-blue-800 flex items-center justify-center space-x-2">
                   <History size={12} /> <span>Pulihkan</span>
                </button>
                <button onClick={() => deletePermanently(r)} className="p-2.5 bg-rose-50 dark:bg-rose-900/20 text-rose-600 rounded-xl border border-rose-100 dark:border-rose-800">
                   <Trash2 size={12} />
                </button>
             </div>
          </div>
        )) : (
          <div className="py-20 text-center bg-white dark:bg-slate-900 rounded-[2rem] border border-dashed border-slate-200 dark:border-slate-800">
             <p className="text-[10px] font-black text-slate-400 uppercase">Arsip {subTab} Kosong</p>
          </div>
        )}
      </div>

      {/* Desktop Table View */}
      <div className="hidden md:block bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse min-w-[1000px]">
            <thead className={`${subTab === 'Meninggal' ? 'bg-rose-50 dark:bg-rose-900/10' : subTab === 'Pindah' ? 'bg-amber-50 dark:bg-amber-900/10' : 'bg-slate-50 dark:bg-slate-800/50'} border-b border-slate-100 dark:border-slate-800`}>
              <tr>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">Kependudukan</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">Nama Lengkap</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400 text-center">Tgl Peristiwa</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">Keterangan / Alasan</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400 text-center">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
              {filteredArchivedData.map((r) => (
                <tr key={r.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/30 transition-all group">
                  <td className="px-6 py-6">
                    <div className="text-[10px] font-bold text-blue-600 dark:text-blue-400 font-mono tracking-tighter">{r.noKK}</div>
                    <div className="text-[10px] text-slate-400 dark:text-slate-500 font-mono">{r.nik}</div>
                  </td>
                  <td className="px-6 py-6">
                    <div className="text-sm font-black uppercase text-slate-800 dark:text-slate-200">{r.fullName}</div>
                    <div className="text-[9px] font-bold text-slate-400 dark:text-slate-500 uppercase">{r.dusun} | {r.relationship.includes('. ') ? r.relationship.split('. ')[1] : r.relationship}</div>
                  </td>
                  <td className="px-6 py-6 text-center">
                    <div className="inline-flex items-center space-x-1.5 px-3 py-1 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-lg shadow-sm">
                       <Calendar size={12} className="text-slate-400" />
                       <span className="text-[11px] font-black text-slate-700 dark:text-slate-300">{formatDate(subTab === 'Meninggal' ? r.deathDate! : subTab === 'Pindah' ? r.moveDate! : r.deleteDate!)}</span>
                    </div>
                  </td>
                  <td className="px-6 py-6">
                    <div className="flex items-start space-x-2 max-w-xs">
                       <MessageSquare size={14} className="text-slate-300 dark:text-slate-700 mt-1 shrink-0" />
                       <div className="text-xs font-bold text-slate-500 dark:text-slate-400 leading-relaxed italic">
                        {subTab === 'Pindah' ? `Pindah ke: ${r.moveDestination}` : subTab === 'Meninggal' ? 'Kematian Penduduk' : r.deleteReason || 'Tanpa alasan'}
                       </div>
                    </div>
                  </td>
                  <td className="px-6 py-6">
                    <div className="flex items-center justify-center space-x-2">
                       {(subTab === 'Pindah' || subTab === 'Terhapus') && <button onClick={() => setViewingFamilyKK(r.noKK)} className="p-2.5 bg-slate-50 dark:bg-slate-800 text-slate-400 dark:text-slate-500 rounded-xl hover:bg-slate-900 dark:hover:bg-blue-600 hover:text-white transition-all shadow-sm" title="Lihat Anggota"><Eye size={16} /></button>}
                       <button onClick={() => restoreData(r)} className="p-2.5 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-xl hover:bg-blue-600 dark:hover:bg-blue-500 hover:text-white transition-all shadow-sm" title="Pulihkan Data"><History size={16} /></button>
                       <button onClick={() => deletePermanently(r)} className="p-2.5 bg-rose-50 dark:bg-rose-900/30 text-rose-400 dark:text-rose-500 rounded-xl hover:bg-rose-600 dark:hover:bg-rose-500 hover:text-white transition-all shadow-sm" title="Hapus Permanen"><Trash2 size={16} /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
      {viewingFamilyKK && <FamilyDetailModal noKK={viewingFamilyKK} residents={residents} setResidents={setResidents} onClose={() => setViewingFamilyKK(null)} />}
    </div>
  );
};

export default ArchivedResidents;

import React, { useState, useMemo, useRef } from 'react';
import { 
  Search, 
  Plus, 
  Trash2, 
  Eye,
  CheckSquare,
  Square,
  Upload,
  BookOpen,
  Loader2,
  MapPin,
  X,
  Edit3,
  Download,
  RefreshCcw,
  Printer,
  Info,
  PlaneLanding,
  Calendar,
  Save,
  MoreVertical,
  ChevronRight,
  User,
  ExternalLink,
  ChevronDown
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { Resident, BloodType, MaritalStatus, Education, ResidentStatus, AppConfig } from '../types';
import { calculateAge, downloadTemplate, downloadCSV } from '../utils/helpers';
import FamilyDetailModal from './FamilyDetailModal';
import EditResidentModal from './EditResidentModal';
import AddResidentModal from './AddResidentModal';

interface PopulationManagementProps {
  residents: Resident[];
  setResidents: React.Dispatch<React.SetStateAction<Resident[]>>;
  config: AppConfig;
}

const PopulationManagement: React.FC<PopulationManagementProps> = ({ residents, setResidents, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const [isPreparingPDF, setIsPreparingPDF] = useState(false);
  const [filters, setFilters] = useState({ dusun: '', rw: '', rt: '' });
  const [viewingFamilyKK, setViewingFamilyKK] = useState<string | null>(null);
  const [editingResident, setEditingResident] = useState<Resident | null>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [deletingFamily, setDeletingFamily] = useState<{item: Resident, ids?: string[]} | null>(null);
  const [movingFamily, setMovingFamily] = useState<Resident | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const activeResidents = useMemo(() => residents.filter(r => r.status === 'Aktif'), [residents]);
  const headOfFamilies = useMemo(() => activeResidents.filter(r => r.isHeadOfFamily), [activeResidents]);

  const dusunList = useMemo(() => Array.from(new Set(activeResidents.map(r => r.dusun))).sort(), [activeResidents]);

  const rwList = useMemo(() => {
    const filtered = filters.dusun ? activeResidents.filter(r => r.dusun === filters.dusun) : activeResidents;
    return Array.from(new Set(filtered.map(r => r.rw))).sort();
  }, [activeResidents, filters.dusun]);

  const rtList = useMemo(() => {
    let filtered = filters.dusun ? activeResidents.filter(r => r.dusun === filters.dusun) : activeResidents;
    if (filters.rw) filtered = filtered.filter(r => r.rw === filters.rw);
    return Array.from(new Set(filtered.map(r => r.rt))).sort();
  }, [activeResidents, filters.dusun, filters.rw]);

  const filteredData = useMemo(() => {
    return headOfFamilies.filter(r => {
      const s = searchTerm.toLowerCase();
      const matchSearch = r.fullName.toLowerCase().includes(s) || r.nik.includes(s) || r.noKK.includes(s);
      const matchDusun = !filters.dusun || r.dusun === filters.dusun;
      const matchRW = !filters.rw || r.rw === filters.rw;
      const matchRT = !filters.rt || r.rt === filters.rt;
      return matchSearch && matchDusun && matchRW && matchRT;
    });
  }, [headOfFamilies, searchTerm, filters]);

  const residentsToExport = useMemo(() => {
    const displayedKKs = new Set(filteredData.map(r => r.noKK.trim()));
    return activeResidents
      .filter(r => displayedKKs.has(r.noKK.trim()))
      .sort((a, b) => {
        if (a.dusun !== b.dusun) return a.dusun.localeCompare(b.dusun);
        if (a.rw !== b.rw) return a.rw.localeCompare(b.rw);
        if (a.rt !== b.rt) return a.rt.localeCompare(b.rt);
        if (a.noKK !== b.noKK) return a.noKK.localeCompare(b.noKK);
        return a.relationship.localeCompare(b.relationship);
      });
  }, [filteredData, activeResidents]);

  const handleDownloadPDF = async () => {
    if (residentsToExport.length === 0) return alert("Tidak ada data untuk dicetak.");
    setIsPreparingPDF(true);
    try {
      const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
      const addHeader = (data: any) => {
        doc.setFontSize(14);
        doc.setFont('helvetica', 'bold');
        doc.text('PEMERINTAH KABUPATEN BLORA', 148.5, 15, { align: 'center' });
        doc.setFontSize(12);
        doc.text('KECAMATAN TODANAN - DESA NGUMBUL', 148.5, 21, { align: 'center' });
        doc.setLineWidth(0.5);
        doc.line(20, 28, 277, 28);
        doc.setFontSize(11);
        doc.text('DAFTAR PENDUDUK BY NAME BY ADDRESS (BNBA)', 148.5, 38, { align: 'center' });
      };

      const tableData = residentsToExport.map((r, idx) => [
        idx + 1, r.fullName.toUpperCase(), r.nik, r.noKK, `${r.dusun} / ${r.rw} / ${r.rt}`,
        r.gender.includes('Laki') ? 'L' : 'P', calculateAge(r.birthDate), r.relationship.split('. ').pop() || r.relationship,
        r.education.split('. ').pop() || r.education, r.job.split('. ').pop()?.toUpperCase() || r.job.toUpperCase()
      ]);

      autoTable(doc, {
        head: [['NO', 'NAMA LENGKAP', 'NIK', 'NOMOR KK', 'ALAMAT', 'JK', 'USIA', 'HUBUNGAN', 'PENDIDIKAN', 'PEKERJAAN']],
        body: tableData,
        startY: 50,
        styles: { fontSize: 7, cellPadding: 1.5 },
        headStyles: { fillColor: [230, 230, 230], textColor: [0, 0, 0] },
        didDrawPage: (data) => { if (data.pageNumber === 1) addHeader(data); }
      });

      const finalY = (doc as any).lastAutoTable.finalY || 150;
      doc.text(`Ngumbul, ${new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' })}`, 230, finalY + 15, { align: 'center' });
      doc.text('KEPALA DESA NGUMBUL', 230, finalY + 20, { align: 'center' });
      doc.text(config.villageHeadName.toUpperCase(), 230, finalY + 40, { align: 'center' });
      doc.save(`BNBA_Ngumbul_${new Date().toISOString().split('T')[0]}.pdf`);
    } catch (error) {
      alert("Gagal membuat PDF.");
    } finally {
      setIsPreparingPDF(false);
    }
  };

  const handleDownloadCSV = () => {
    if (residentsToExport.length === 0) return alert("Tidak ada data untuk diekspor.");
    const dataToExport = residentsToExport.map(r => ({
      'Dusun': r.dusun, 'RW': r.rw, 'RT': r.rt, 'No. KK': r.noKK, 'NIK': r.nik, 
      'Nama Lengkap': r.fullName, 'Hubungan': r.relationship, 'Tgl Lahir': r.birthDate,
      'Usia': calculateAge(r.birthDate), 'JK': r.gender, 'Gol. Darah': r.bloodType,
      'Status': r.maritalStatus, 'Pendidikan': r.education, 'Pekerjaan': r.job
    }));
    downloadCSV(dataToExport, `BNBA_Ngumbul_${new Date().toISOString().split('T')[0]}`);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const lines = text.split('\n').filter(line => line.trim() !== '');
        const delimiter = lines[0].includes(';') ? ';' : ',';
        const headers = lines[0].split(delimiter).map(h => h.trim().replace(/^"|"$/g, ''));
        const newResidents: Resident[] = lines.slice(1).map((line, index) => {
          const values = line.split(delimiter).map(v => v.trim().replace(/^"|"$/g, ''));
          const item: any = {};
          headers.forEach((h, i) => item[h] = values[i] || '');
          const rel = item['Status Hubungan dalam Keluarga'] || item['Hubungan'] || '';
          return {
            id: `imp-${Date.now()}-${index}`,
            dusun: item['Dusun'] || '-',
            rt: item['RT'] || '-',
            rw: item['RW'] || '-',
            noKK: (item['No.KK'] || item['No. KK'] || '').replace(/\D/g, '').slice(0, 16),
            nik: (item['NIK'] || '').replace(/\D/g, '').slice(0, 16),
            fullName: (item['Nama Lengkap'] || '-').toUpperCase(),
            relationship: rel,
            birthPlace: item['Tempat Lahir'] || '', 
            birthDate: item['Tanggal Lahir'] || item['Tgl Lahir'] || '1990-01-01',
            gender: (item['Jenis Kelamin'] || item['JK'] || '').includes('P') ? 'Perempuan' : 'Laki-laki',
            bloodType: (item['Golongan Darah'] || item['Gol. Darah'] || 'Tidak Tahu') as BloodType,
            maritalStatus: (item['Status Perkawinan'] || item['Status'] || 'Belum Kawin') as MaritalStatus,
            education: (item['Pendidikan Tertinggi'] || item['Pendidikan'] || 'SMA') as Education,
            job: item['Pekerjaan'] || '',
            fatherName: item['Nama Ayah Kandung'] || '',
            motherName: item['Nama Ibu Kandung'] || '',
            isHeadOfFamily: rel.toLowerCase().includes('kepala keluarga') || rel.startsWith('1'),
            status: 'Aktif' as ResidentStatus
          };
        });
        setResidents(prev => [...prev, ...newResidents]);
        setIsImporting(false);
        alert(`Berhasil mengimpor ${newResidents.length} data.`);
        if (fileInputRef.current) fileInputRef.current.value = '';
      } catch (err) {
        alert('Gagal impor.');
        setIsImporting(false);
      }
    };
    reader.readAsText(file);
  };

  const handleArchiveMove = (destination: string, date: string) => {
    if (!movingFamily) return;
    setResidents(prev => prev.map(r => 
      r.noKK === movingFamily.noKK ? {
        ...r, status: 'Pindah' as ResidentStatus, moveDestination: destination, moveDate: date
      } : r
    ));
    setMovingFamily(null);
  };

  return (
    <div className="space-y-4 md:space-y-6 pb-20 md:pb-10">
      {(isImporting || isPreparingPDF) && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl text-center">
             <Loader2 className="mx-auto text-blue-600 animate-spin mb-4" size={40} />
             <p className="text-sm font-black uppercase text-slate-900 dark:text-white">{isPreparingPDF ? "Cetak PDF..." : "Memproses..."}</p>
          </div>
        </div>
      )}

      {/* Main Action Bar */}
      <div className="flex flex-col gap-4 bg-white dark:bg-slate-900 p-4 rounded-3xl shadow-sm border border-slate-200 dark:border-slate-800 no-print">
        <div className="flex items-center bg-slate-100 dark:bg-slate-800 rounded-2xl px-4 py-3 border border-slate-200 dark:border-slate-700 w-full focus-within:bg-white dark:focus-within:bg-slate-800 transition-all">
          <Search size={18} className="text-slate-400 mr-3" />
          <input 
            type="text" 
            placeholder="Cari Nama/NIK/KK..."
            className="bg-transparent border-none outline-none text-sm w-full font-bold text-slate-900 dark:text-white"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex items-center overflow-x-auto gap-2 pb-1 scrollbar-hide">
          <button onClick={() => setIsAddModalOpen(true)} className="flex items-center space-x-2 px-4 py-2.5 bg-slate-900 dark:bg-blue-600 text-white rounded-xl text-[10px] font-black uppercase whitespace-nowrap shadow-md">
            <Plus size={14} /> <span>Tambah KK</span>
          </button>
          <button onClick={handleDownloadPDF} className="flex items-center space-x-2 px-4 py-2.5 bg-rose-600 text-white rounded-xl text-[10px] font-black uppercase whitespace-nowrap">
            <Printer size={14} /> <span>Cetak</span>
          </button>
          <button onClick={handleDownloadCSV} className="flex items-center space-x-2 px-4 py-2.5 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase whitespace-nowrap">
            <Download size={14} /> <span>CSV</span>
          </button>
          <label className="flex items-center space-x-2 px-4 py-2.5 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 border border-blue-200 dark:border-blue-800 rounded-xl text-[10px] font-black uppercase whitespace-nowrap cursor-pointer">
            <Upload size={14} /> <span>Import</span>
            <input ref={fileInputRef} type="file" className="hidden" onChange={handleImport} accept=".csv" />
          </label>
        </div>
      </div>

      {/* Advanced Filter Bar (Mobile Optimized) */}
      <div className="bg-white dark:bg-slate-900 p-3 rounded-2xl md:rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-x-auto scrollbar-hide">
        <div className="flex items-center space-x-3 min-w-max">
          <div className="flex items-center bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-3 py-2">
            <MapPin size={12} className="text-slate-400 mr-2" />
            <select className="bg-transparent text-[10px] font-black uppercase outline-none text-slate-900 dark:text-white" value={filters.dusun} onChange={(e) => setFilters({ ...filters, dusun: e.target.value, rw: '', rt: '' })}>
              <option value="">Dusun</option>
              {dusunList.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
          <div className="flex items-center bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-3 py-2">
            <span className="text-[9px] font-black text-slate-400 mr-2 uppercase">RW</span>
            <select className="bg-transparent text-[10px] font-black outline-none text-slate-900 dark:text-white" value={filters.rw} onChange={(e) => setFilters({ ...filters, rw: e.target.value, rt: '' })} disabled={!filters.dusun}>
              <option value="">-</option>
              {rwList.map(rw => <option key={rw} value={rw}>{rw}</option>)}
            </select>
          </div>
          <div className="flex items-center bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-3 py-2">
            <span className="text-[9px] font-black text-slate-400 mr-2 uppercase">RT</span>
            <select className="bg-transparent text-[10px] font-black outline-none text-slate-900 dark:text-white" value={filters.rt} onChange={(e) => setFilters({ ...filters, rt: e.target.value })} disabled={!filters.rw}>
              <option value="">-</option>
              {rtList.map(rt => <option key={rt} value={rt}>{rt}</option>)}
            </select>
          </div>
          <button onClick={() => setFilters({ dusun: '', rw: '', rt: '' })} className="p-2 text-slate-400 hover:text-slate-900 transition-all"><RefreshCcw size={14} /></button>
          <div className="text-[10px] font-black text-slate-400 uppercase bg-slate-100 dark:bg-slate-800 px-3 py-2 rounded-xl">
            {filteredData.length} KK
          </div>
        </div>
      </div>

      {/* Screen Card View (Mobile) */}
      <div className="grid grid-cols-1 md:hidden gap-4 no-print px-1">
        {filteredData.length > 0 ? filteredData.map((r) => (
          <div key={r.id} className="bg-white dark:bg-slate-900 p-5 rounded-[1.5rem] border border-slate-200 dark:border-slate-800 shadow-sm relative overflow-hidden group">
             {/* Gradient Accent */}
             <div className="absolute top-0 left-0 w-1 h-full bg-blue-600"></div>

             <div className="flex justify-between items-start mb-4">
                <div className="flex items-center space-x-3 min-w-0">
                   <div className="w-10 h-10 bg-slate-100 dark:bg-slate-800 rounded-xl flex items-center justify-center text-slate-400 shrink-0">
                      <User size={20} />
                   </div>
                   <div className="min-w-0 flex-1">
                      <h4 className="text-[13px] font-black uppercase text-slate-900 dark:text-white leading-tight truncate">{r.fullName}</h4>
                      <p className="text-[10px] font-mono text-blue-600 dark:text-blue-400 mt-0.5 truncate">KK: {r.noKK}</p>
                   </div>
                </div>
                <div className="flex items-center space-x-1 shrink-0 ml-2">
                   <button onClick={() => setViewingFamilyKK(r.noKK)} className="p-2 bg-blue-50 dark:bg-blue-900/30 text-blue-600 rounded-lg"><Eye size={16} /></button>
                   <button onClick={() => setEditingResident(r)} className="p-2 bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-400 rounded-lg"><Edit3 size={16} /></button>
                </div>
             </div>

             <div className="grid grid-cols-2 gap-4 border-t border-slate-100 dark:border-slate-800 pt-3 mb-4">
                <div className="min-w-0">
                   <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5 tracking-widest">Wilayah</p>
                   <p className="text-[10px] font-bold text-slate-700 dark:text-slate-300 uppercase truncate">{r.dusun}</p>
                   <p className="text-[9px] font-black text-slate-500 uppercase">RT {r.rt} / RW {r.rw}</p>
                </div>
                <div className="min-w-0">
                   <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5 tracking-widest">Identitas</p>
                   <p className="text-[10px] font-mono font-bold text-slate-700 dark:text-slate-300 truncate">{r.nik}</p>
                   <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-full inline-block mt-1 ${r.gender.includes('Laki') ? 'bg-blue-100 text-blue-600' : 'bg-pink-100 text-pink-600'}`}>
                      {r.gender.includes('Laki') ? 'Laki-laki' : 'Perempuan'}
                   </span>
                </div>
             </div>

             <div className="flex items-center gap-2 pt-2 border-t border-slate-50 dark:border-slate-800">
                <button onClick={() => setMovingFamily(r)} className="flex-1 py-2.5 bg-amber-50 dark:bg-amber-900/20 text-amber-600 dark:text-amber-400 rounded-xl text-[9px] font-black uppercase border border-amber-100 dark:border-amber-800 flex items-center justify-center space-x-2">
                   <PlaneLanding size={12} /> <span>Pindah</span>
                </button>
                <button onClick={() => setDeletingFamily({ item: r })} className="flex-1 py-2.5 bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400 rounded-xl text-[9px] font-black uppercase border border-rose-100 dark:border-rose-800 flex items-center justify-center space-x-2">
