import React, { useState, useMemo } from 'react';
import { Search, MapPin, Skull, PlaneLanding, History, Trash2, Calendar, FileText, Eye, AlertTriangle, MessageSquare, User } from 'lucide-react';
import { Resident, ResidentStatus } from '../types';
import { calculateAge, formatDate } from '../utils/helpers';
import FamilyDetailModal from './FamilyDetailModal';

interface ArchivedResidentsProps {
  residents: Resident[];
  setResidents: React.Dispatch<React.SetStateAction<Resident[]>>;
}

const ArchivedResidents: React.FC<ArchivedResidentsProps> = ({ residents, setResidents }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [subTab, setSubTab] = useState<'Meninggal' | 'Pindah' | 'Terhapus'>('Meninggal');
  const [viewingFamilyKK, setViewingFamilyKK] = useState<string | null>(null);

  const filteredArchivedData = useMemo(() => {
    return residents.filter(r => {
      const matchStatus = r.status === subTab;
      const matchLevel = (subTab === 'Pindah' || subTab === 'Terhapus') ? r.isHeadOfFamily : true;
      const matchSearch = 
        r.fullName.toLowerCase().includes(searchTerm.toLowerCase()) ||
        r.nik.includes(searchTerm) ||
        r.noKK.includes(searchTerm);
      return matchStatus && matchLevel && matchSearch;
    });
  }, [residents, searchTerm, subTab]);

  const restoreData = (item: Resident) => {
    const msg = (subTab === 'Pindah' || subTab === 'Terhapus')
      ? `Pulihkan data keluarga ${item.fullName} (KK: ${item.noKK}) ke status Aktif?`
      : `Pulihkan ${item.fullName} ke status Aktif?`;

    if (window.confirm(msg)) {
      setResidents(prev => prev.map(r => {
        const isTargetRecord = (subTab === 'Pindah' || subTab === 'Terhapus') 
          ? r.noKK.trim() === item.noKK.trim() 
          : r.id === item.id;

        if (isTargetRecord && r.status === subTab) {
          return { 
            ...r, 
            status: 'Aktif' as ResidentStatus, 
            deathDate: undefined, 
            moveDate: undefined, 
            moveDestination: undefined,
            deleteDate: undefined,
            deleteReason: undefined
          };
        }
        return r;
      }));
    }
  };

  const deletePermanently = (item: Resident) => {
    const msg = (subTab === 'Pindah' || subTab === 'Terhapus')
      ? `Hapus PERMANEN keluarga ${item.fullName}? Data akan benar-benar dibuang dari sistem!`
      : `Hapus PERMANEN data ${item.fullName}? Data akan benar-benar dibuang dari sistem!`;

    if (window.confirm(msg)) {
      setResidents(prev => prev.filter(r => {
        const shouldDelete = (subTab === 'Pindah' || subTab === 'Terhapus') ? r.noKK.trim() === item.noKK.trim() : r.id === item.id;
        if (shouldDelete && r.status === subTab) return false;
        return true;
      }));
    }
  };

  const tabConfigs = {
    Meninggal: { color: 'bg-rose-600', icon: Skull, label: 'Kematian' },
    Pindah: { color: 'bg-amber-500', icon: PlaneLanding, label: 'Pindah' },
    Terhapus: { color: 'bg-slate-700', icon: AlertTriangle, label: 'Terhapus' }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      {/* Tab Switcher - Mobile Optimized */}
      <div className="flex items-center space-x-1.5 bg-white dark:bg-slate-900 p-1.5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800 w-full overflow-x-auto scrollbar-hide">
        {(Object.keys(tabConfigs) as Array<keyof typeof tabConfigs>).map(tabKey => {
          const Config = tabConfigs[tabKey];
          return (
            <button 
              key={tabKey}
              onClick={() => setSubTab(tabKey)} 
              className={`flex-1 flex items-center justify-center space-x-2 px-4 py-3 rounded-xl text-[10px] font-black uppercase transition-all whitespace-nowrap ${subTab === tabKey ? `${Config.color} text-white shadow-lg` : 'text-slate-400 dark:text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
            >
              <Config.icon size={14} />
              <span>{Config.label}</span>
            </button>
          );
        })}
      </div>

      {/* Search Bar */}
      <div className="bg-white dark:bg-slate-900 p-4 rounded-3xl shadow-sm border border-slate-200 dark:border-slate-800 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex-1 flex items-center bg-slate-50 dark:bg-slate-800 rounded-2xl px-5 py-3 border border-slate-100 dark:border-slate-700 w-full focus-within:bg-white dark:focus-within:bg-slate-800 transition-all">
          <Search size={18} className="text-slate-400 mr-3" />
          <input type="text" placeholder={`Cari di arsip...`} className="bg-transparent border-none outline-none text-sm w-full font-bold text-slate-900 dark:text-white" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
        </div>
        <div className="hidden md:block text-[10px] font-black text-slate-400 uppercase tracking-widest">
           {filteredArchivedData.length} entitas arsip
        </div>
      </div>

      {/* Mobile Card View */}
      <div className="grid grid-cols-1 md:hidden gap-4 px-1">
        {filteredArchivedData.length > 0 ? filteredArchivedData.map((r) => (
          <div key={r.id} className="bg-white dark:bg-slate-900 p-5 rounded-[1.5rem] border border-slate-200 dark:border-slate-800 shadow-sm relative overflow-hidden group transition-all active:scale-[0.98]">
             <div className={`absolute top-0 left-0 w-1 h-full ${tabConfigs[subTab].color}`}></div>

             <div className="flex justify-between items-start mb-4">
                <div className="flex items-center space-x-3 min-w-0 flex-1">
                   <div className="w-10 h-10 bg-slate-100 dark:bg-slate-800 rounded-xl flex items-center justify-center text-slate-400 shrink-0">
                      <User size={20} />
                   </div>
                   <div className="min-w-0 flex-1">
                      <h4 className="text-[13px] font-black uppercase text-slate-900 dark:text-white leading-tight truncate">{r.fullName}</h4>
                      <p className="text-[10px] font-mono text-slate-500 dark:text-slate-400 mt-0.5 truncate font-bold">NIK: {r.nik}</p>
                   </div>
                </div>
                {/* Mobile Anggota button if applicable */}
                {(subTab === 'Pindah' || subTab === 'Terhapus') && (
                  <button onClick={() => setViewingFamilyKK(r.noKK)} className="p-2 ml-2 bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded-lg shrink-0">
                    <Eye size={16} />
                  </button>
                )}
             </div>

             <div className="space-y-3 mb-4">
                <div className="grid grid-cols-2 gap-4">
                   <div className="min-w-0">
                      <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5 tracking-widest">Tgl Peristiwa</p>
                      <div className="flex items-center space-x-1.5">
                         <Calendar size={10} className="text-slate-400" />
                         <span className="text-[10px] font-black text-slate-700 dark:text-slate-300">
                           {formatDate(subTab === 'Meninggal' ? r.deathDate! : subTab === 'Pindah' ? r.moveDate! : r.deleteDate!)}
                         </span>
                      </div>
                   </div>
                   <div className="min-w-0">
                      <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5 tracking-widest">Status Hub.</p>
                      <p className="text-[10px] font-bold text-slate-600 dark:text-slate-400 uppercase truncate">
                        {r.relationship.includes('. ') ? r.relationship.split('. ')[1] : r.relationship}
                      </p>
                   </div>
                </div>

                <div className="bg-slate-50 dark:bg-slate-800/50 p-3 rounded-xl border border-dashed border-slate-200 dark:border-slate-700 overflow-hidden">
                   <p className="text-[8px] font-black text-slate-400 uppercase mb-1 tracking-widest">Keterangan / Alasan</p>
                   <div className="flex items-start space-x-2">
                      <MessageSquare size={12} className="text-slate-300 dark:text-slate-600 mt-0.5 shrink-0" />
                      <p className="text-[10px] font-bold text-slate-600 dark:text-slate-300 leading-relaxed italic break-words">
                        {subTab === 'Pindah' ? `Pindah ke: ${r.moveDestination}` : subTab === 'Meninggal' ? 'Kematian Penduduk' : r.deleteReason || 'Tanpa alasan'}
                      </p>
                   </div>
                </div>
             </div>

             <div className="flex items-center gap-2 pt-2 border-t border-slate-50 dark:border-slate-800">
                <button onClick={() => restoreData(r)} className="flex-1 py-2.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-xl text-[9px] font-black uppercase border border-blue-100 dark:border-blue-800 flex items-center justify-center space-x-2 shadow-sm">
                   <History size={12} /> <span>Pulihkan</span>
                </button>
                <button onClick={() => deletePermanently(r)} className="p-2.5 bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400 rounded-xl border border-rose-100 dark:border-rose-800">
                   <Trash2 size={12} />
                </button>
             </div>
          </div>
        )) : (
          <div className="py-20 text-center bg-white dark:bg-slate-900 rounded-[2rem] border border-dashed border-slate-200 dark:border-slate-800">
             <p className="text-[10px] font-black text-slate-400 uppercase">Arsip {subTab} Kosong</p>
          </div>
        )}
      </div>

      {/* Desktop Table View */}
      <div className="hidden md:block bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse min-w-[1000px]">
            <thead className={`${subTab === 'Meninggal' ? 'bg-rose-50 dark:bg-rose-900/10' : subTab === 'Pindah' ? 'bg-amber-50 dark:bg-amber-900/10' : 'bg-slate-50 dark:bg-slate-800/50'} border-b border-slate-100 dark:border-slate-800`}>
              <tr>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">Kependudukan</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">Nama Lengkap</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400 text-center">Tgl Peristiwa</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">Keterangan / Alasan</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400 text-center">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
              {filteredArchivedData.map((r) => (
                <tr key={r.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-all group text-slate-900 dark:text-slate-100">
                  <td className="px-6 py-6">
                    <div className="text-[10px] font-bold text-blue-600 dark:text-blue-400 font-mono tracking-tighter">KK: {r.noKK}</div>
                    <div className="text-[10px] text-slate-400 dark:text-slate-500 font-mono font-bold">{r.nik}</div>
                  </td>
                  <td className="px-6 py-6">
                    <div 
                      className="text-sm font-black uppercase text-slate-800 dark:text-slate-200 cursor-pointer hover:text-blue-600 transition-colors"
                      onClick={() => (subTab === 'Pindah' || subTab === 'Terhapus') ? setViewingFamilyKK(r.noKK) : null}
                    >
                      {r.fullName}
                    </div>
                    <div className="text-[9px] font-bold text-slate-400 dark:text-slate-500 uppercase">{r.dusun} | {r.relationship.includes('. ') ? r.relationship.split('. ')[1] : r.relationship}</div>
                  </td>
                  <td className="px-6 py-6 text-center">
                    <div className="inline-flex items-center space-x-1.5 px-3 py-1 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-lg shadow-sm">
                       <Calendar size={12} className="text-slate-400" />
                       <span className="text-[11px] font-black text-slate-700 dark:text-slate-300">{formatDate(subTab === 'Meninggal' ? r.deathDate! : subTab === 'Pindah' ? r.moveDate! : r.deleteDate!)}</span>
                    </div>
                  </td>
                  <td className="px-6 py-6">
                    <div className="flex items-start space-x-2 max-w-xs">
                       <MessageSquare size={14} className="text-slate-300 dark:text-slate-700 mt-1 shrink-0" />
                       <div className="text-xs font-bold text-slate-600 dark:text-slate-400 leading-relaxed italic">
                        {subTab === 'Pindah' ? `Pindah ke: ${r.moveDestination}` : subTab === 'Meninggal' ? 'Kematian Penduduk' : r.deleteReason || 'Tanpa alasan'}
                       </div>
                    </div>
                  </td>
                  <td className="px-6 py-6">
                    <div className="flex items-center justify-center space-x-2">
                       {(subTab === 'Pindah' || subTab === 'Terhapus') && <button onClick={() => setViewingFamilyKK(r.noKK)} className="p-2.5 bg-slate-50 dark:bg-slate-800 text-slate-400 dark:text-slate-500 rounded-xl hover:bg-slate-900 dark:hover:bg-blue-600 hover:text-white transition-all shadow-sm" title="Lihat Anggota"><Eye size={16} /></button>}
                       <button onClick={() => restoreData(r)} className="p-2.5 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-xl hover:bg-blue-600 dark:hover:bg-blue-500 hover:text-white transition-all shadow-sm" title="Pulihkan Data"><History size={16} /></button>
                       <button onClick={() => deletePermanently(r)} className="p-2.5 bg-rose-50 dark:bg-rose-900/30 text-rose-400 dark:text-rose-500 rounded-xl hover:bg-rose-600 dark:hover:bg-rose-500 hover:text-white transition-all shadow-sm" title="Hapus Permanen"><Trash2 size={16} /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
      {viewingFamilyKK && <FamilyDetailModal noKK={viewingFamilyKK} residents={residents} setResidents={setResidents} onClose={() => setViewingFamilyKK(null)} />}
    </div>
  );
};

