             <div className={`absolute top-0 left-0 w-1.5 h-full ${tabConfigs[subTab].color}`}></div>

             <div className="flex justify-between items-start mb-4">
                <div className="flex items-center space-x-3 min-w-0 flex-1">
                   <div className="w-10 h-10 bg-slate-100 dark:bg-slate-800 rounded-xl flex items-center justify-center text-slate-400 shrink-0">
                      <User size={20} />
                   </div>
                   <div className="min-w-0 flex-1">
                      <button 
                        onClick={() => (subTab === 'Pindah' || subTab === 'Terhapus') ? setViewingFamilyKK(r.noKK) : null}
