                  setResidents(prev => prev.map(r => r.noKK === deletingFamily.item.noKK ? {...r, status: 'Terhapus' as ResidentStatus, deleteDate: new Date().toISOString().split('T')[0], deleteReason: 'Mobile'} : r));
