  // Menu Bottom Nav (Utama: Beranda, Data, Cari, Arsip, Profil)
  const bottomNavItems = [
    { id: 'dashboard', label: 'Beranda', icon: LayoutDashboard },
    { id: 'penduduk', label: 'Data', icon: Users },
    { id: 'pencarian', label: 'Cari', icon: SearchIcon },
    { id: 'arsip', label: 'Arsip', icon: Archive },
    { id: 'profil', label: 'Profil', icon: Settings },
  ];

  const getInitials = (name: string) => {
    if (!name) return 'AD';
    return name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
  };

  const sidebarWidth = isSidebarCollapsed ? 'w-20' : 'w-64';

  return (
    <div className={`min-h-screen flex flex-col transition-colors duration-300 ${theme === 'dark' ? 'dark bg-slate-950' : 'bg-slate-50'}`}>
      <div className="flex w-full flex-1 bg-inherit text-slate-900 dark:text-slate-100">
        {/* Sidebar Desktop */}
        <aside className={`hidden md:flex flex-col ${sidebarWidth} bg-slate-900 text-white shadow-xl fixed h-full transition-all duration-300 z-40`}>
          <div className={`p-6 border-b border-slate-800 flex items-center ${isSidebarCollapsed ? 'justify-center' : 'space-x-3'}`}>
            <img 
              src={config.logoUrl || "https://upload.wikimedia.org/wikipedia/commons/1/1d/Lambang_Kabupaten_Blora.png"} 
              alt="Logo" 
              className="w-10 h-10 rounded-lg bg-white p-1 min-w-[40px]"
            />
            {!isSidebarCollapsed && (
              <div className="animate-in fade-in duration-300 min-w-0 flex-1">
                <h1 className="font-bold text-base lg:text-lg leading-tight uppercase tracking-tighter truncate">{config.appName}</h1>
                <p className="text-[10px] text-slate-400 font-medium uppercase tracking-widest leading-tight mt-1 whitespace-normal break-words">
                  {config.subtitle}
                </p>
              </div>
            )}
          </div>

          <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
            {menuItems.map((item) => (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id)}
                className={`w-full flex items-center rounded-xl transition-all group ${
                  isSidebarCollapsed ? 'justify-center p-3' : 'space-x-3 px-4 py-3'
                } ${
                  activeTab === item.id 
                    ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/20' 
                    : 'text-slate-400 hover:bg-slate-800 hover:text-white'
                }`}
              >
                <item.icon size={20} />
                {!isSidebarCollapsed && <span className="font-bold text-sm">{item.label}</span>}
              </button>
            ))}
          </nav>

          <div className="p-4 border-t border-slate-800">
            <button 
              onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
              className={`w-full flex items-center rounded-lg text-slate-400 hover:bg-slate-800 hover:text-white transition-all text-sm font-bold ${
                isSidebarCollapsed ? 'justify-center p-3' : 'space-x-3 px-4 py-3'
              }`}
            >
              {isSidebarCollapsed ? <PanelLeftOpen size={20} /> : <PanelLeftClose size={20} />}
              {!isSidebarCollapsed && <span className="font-bold text-sm">Sembunyikan</span>}
            </button>
          </div>
        </aside>

        {/* Main Content Area */}
        <div className={`flex-1 flex flex-col transition-all duration-300 ${isSidebarCollapsed ? 'md:ml-20' : 'md:ml-64'} pb-20 md:pb-0`}>
          <header className="bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 h-14 md:h-16 flex items-center justify-between px-4 md:px-8 sticky top-0 z-30">
            <div className="flex items-center space-x-3">
              <div className="md:hidden flex items-center space-x-2">
                <img src={config.logoUrl} alt="Logo" className="w-7 h-7 rounded p-0.5 bg-slate-100" />
                <h1 className="text-xs font-black uppercase tracking-tighter truncate max-w-[120px] text-slate-950 dark:text-white">{config.appName}</h1>
              </div>
              <h2 className="hidden md:block text-lg font-black uppercase tracking-widest text-slate-950 dark:text-slate-100">
                {menuItems.find(i => i.id === activeTab)?.label}
              </h2>
            </div>

            <div className="flex items-center space-x-1.5">
               <button 
                 onClick={toggleTheme}
                 className="p-2 rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-amber-400 hover:bg-slate-200 transition-all"
               >
                 {theme === 'light' ? <Moon size={15} /> : <Sun size={15} />}
               </button>

               <div className="flex items-center space-x-2 bg-slate-100 dark:bg-slate-800 pl-1 pr-2.5 py-1 rounded-full">
                  <div className="w-6 h-6 rounded-full bg-slate-900 dark:bg-blue-600 flex items-center justify-center text-white text-[8px] font-black uppercase">
                    {getInitials(config.operatorName)}
                  </div>
                  <span className="hidden lg:inline text-[9px] font-black text-slate-950 dark:text-slate-300 uppercase truncate max-w-[80px]">
                    {config.operatorName}
                  </span>
               </div>
            </div>
          </header>

          <main className="flex-1 p-3 md:p-8 overflow-x-hidden">
            {children}
          </main>
        </div>

        {/* Bottom Navigation (Mobile Only) */}
        <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-white dark:bg-slate-900 backdrop-blur-xl border-t border-slate-200 dark:border-slate-800 flex justify-around items-center px-1 py-2.5 z-[60] shadow-[0_-8px_30px_rgba(0,0,0,0.08)]">
          {bottomNavItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`flex flex-col items-center justify-center min-w-[50px] transition-all ${
                activeTab === item.id ? 'text-blue-600 scale-105' : 'text-slate-400'
              }`}
            >
              <item.icon size={activeTab === item.id ? 20 : 18} strokeWidth={activeTab === item.id ? 3 : 2} />
              <span className={`text-[7px] font-black uppercase mt-1.5 tracking-tighter ${activeTab === item.id ? 'opacity-100' : 'opacity-70'}`}>
                {item.label}
              </span>
            </button>
          ))}
        </nav>
      </div>
    </div>
  );
};

export default Layout;

import React, { useState, useMemo, useRef } from 'react';
import { 
  Search, 
  Plus, 
  Trash2, 
  Eye,
  CheckSquare,
  Square,
  Upload,
  BookOpen,
  Loader2,
  MapPin,
  X,
  Edit3,
  Download,
  RefreshCcw,
  Printer,
  Info,
  PlaneLanding,
  Calendar,
  Save,
  MoreVertical,
  ChevronRight,
  User,
  ExternalLink,
  ChevronDown
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { Resident, BloodType, MaritalStatus, Education, ResidentStatus, AppConfig } from '../types';
import { calculateAge, downloadTemplate, downloadCSV } from '../utils/helpers';
import FamilyDetailModal from './FamilyDetailModal';
import EditResidentModal from './EditResidentModal';
import AddResidentModal from './AddResidentModal';

interface PopulationManagementProps {
  residents: Resident[];
  setResidents: React.Dispatch<React.SetStateAction<Resident[]>>;
  config: AppConfig;
}

const PopulationManagement: React.FC<PopulationManagementProps> = ({ residents, setResidents, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const [isPreparingPDF, setIsPreparingPDF] = useState(false);
  const [filters, setFilters] = useState({ dusun: '', rw: '', rt: '' });
  const [viewingFamilyKK, setViewingFamilyKK] = useState<string | null>(null);
  const [editingResident, setEditingResident] = useState<Resident | null>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [deletingFamily, setDeletingFamily] = useState<{item: Resident, ids?: string[]} | null>(null);
  const [movingFamily, setMovingFamily] = useState<Resident | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const activeResidents = useMemo(() => residents.filter(r => r.status === 'Aktif'), [residents]);
  const headOfFamilies = useMemo(() => activeResidents.filter(r => r.isHeadOfFamily), [activeResidents]);

  const dusunList = useMemo(() => Array.from(new Set(activeResidents.map(r => r.dusun))).sort(), [activeResidents]);

  const rwList = useMemo(() => {
    const filtered = filters.dusun ? activeResidents.filter(r => r.dusun === filters.dusun) : activeResidents;
    return Array.from(new Set(filtered.map(r => r.rw))).sort();
  }, [activeResidents, filters.dusun]);

  const rtList = useMemo(() => {
    let filtered = filters.dusun ? activeResidents.filter(r => r.dusun === filters.dusun) : activeResidents;
    if (filters.rw) filtered = filtered.filter(r => r.rw === filters.rw);
    return Array.from(new Set(filtered.map(r => r.rt))).sort();
  }, [activeResidents, filters.dusun, filters.rw]);

  const filteredData = useMemo(() => {
    return headOfFamilies.filter(r => {
      const s = searchTerm.toLowerCase();
      const matchSearch = r.fullName.toLowerCase().includes(s) || r.nik.includes(s) || r.noKK.includes(s);
      const matchDusun = !filters.dusun || r.dusun === filters.dusun;
      const matchRW = !filters.rw || r.rw === filters.rw;
      const matchRT = !filters.rt || r.rt === filters.rt;
      return matchSearch && matchDusun && matchRW && matchRT;
    });
  }, [headOfFamilies, searchTerm, filters]);

  const residentsToExport = useMemo(() => {
    const displayedKKs = new Set(filteredData.map(r => r.noKK.trim()));
    return activeResidents
      .filter(r => displayedKKs.has(r.noKK.trim()))
      .sort((a, b) => {
        if (a.dusun !== b.dusun) return a.dusun.localeCompare(b.dusun);
        if (a.rw !== b.rw) return a.rw.localeCompare(b.rw);
        if (a.rt !== b.rt) return a.rt.localeCompare(b.rt);
        if (a.noKK !== b.noKK) return a.noKK.localeCompare(b.noKK);
        return a.relationship.localeCompare(b.relationship);
      });
  }, [filteredData, activeResidents]);

  const handleDownloadPDF = async () => {
    if (residentsToExport.length === 0) return alert("Tidak ada data untuk dicetak.");
    setIsPreparingPDF(true);
    try {
      const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
      const addHeader = (data: any) => {
        doc.setFontSize(14);
        doc.setFont('helvetica', 'bold');
        doc.text('PEMERINTAH KABUPATEN BLORA', 148.5, 15, { align: 'center' });
        doc.setFontSize(12);
        doc.text('KECAMATAN TODANAN - DESA NGUMBUL', 148.5, 21, { align: 'center' });
        doc.setLineWidth(0.5);
        doc.line(20, 28, 277, 28);
        doc.setFontSize(11);
        doc.text('DAFTAR PENDUDUK BY NAME BY ADDRESS (BNBA)', 148.5, 38, { align: 'center' });
      };

      const tableData = residentsToExport.map((r, idx) => [
        idx + 1, r.fullName.toUpperCase(), r.nik, r.noKK, `${r.dusun} / ${r.rw} / ${r.rt}`,
        r.gender.includes('Laki') ? 'L' : 'P', calculateAge(r.birthDate), r.relationship.split('. ').pop() || r.relationship,
        r.education.split('. ').pop() || r.education, r.job.split('. ').pop()?.toUpperCase() || r.job.toUpperCase()
      ]);

      autoTable(doc, {
        head: [['NO', 'NAMA LENGKAP', 'NIK', 'NOMOR KK', 'ALAMAT', 'JK', 'USIA', 'HUBUNGAN', 'PENDIDIKAN', 'PEKERJAAN']],
        body: tableData,
        startY: 50,
        styles: { fontSize: 7, cellPadding: 1.5 },
        headStyles: { fillColor: [230, 230, 230], textColor: [0, 0, 0] },
        didDrawPage: (data) => { if (data.pageNumber === 1) addHeader(data); }
      });

      const finalY = (doc as any).lastAutoTable.finalY || 150;
      doc.text(`Ngumbul, ${new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' })}`, 230, finalY + 15, { align: 'center' });
      doc.text('KEPALA DESA NGUMBUL', 230, finalY + 20, { align: 'center' });
      doc.text(config.villageHeadName.toUpperCase(), 230, finalY + 40, { align: 'center' });
      doc.save(`BNBA_Ngumbul_${new Date().toISOString().split('T')[0]}.pdf`);
    } catch (error) {
      alert("Gagal membuat PDF.");
    } finally {
      setIsPreparingPDF(false);
    }
  };

  const handleDownloadCSV = () => {
    if (residentsToExport.length === 0) return alert("Tidak ada data untuk diekspor.");
    const dataToExport = residentsToExport.map(r => ({
      'Dusun': r.dusun, 'RW': r.rw, 'RT': r.rt, 'No. KK': r.noKK, 'NIK': r.nik, 
      'Nama Lengkap': r.fullName, 'Hubungan': r.relationship, 'Tgl Lahir': r.birthDate,
      'Usia': calculateAge(r.birthDate), 'JK': r.gender, 'Gol. Darah': r.bloodType,
      'Status': r.maritalStatus, 'Pendidikan': r.education, 'Pekerjaan': r.job
    }));
    downloadCSV(dataToExport, `BNBA_Ngumbul_${new Date().toISOString().split('T')[0]}`);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const lines = text.split('\n').filter(line => line.trim() !== '');
        const delimiter = lines[0].includes(';') ? ';' : ',';
        const headers = lines[0].split(delimiter).map(h => h.trim().replace(/^"|"$/g, ''));
        const newResidents: Resident[] = lines.slice(1).map((line, index) => {
          const values = line.split(delimiter).map(v => v.trim().replace(/^"|"$/g, ''));
          const item: any = {};
          headers.forEach((h, i) => item[h] = values[i] || '');
          const rel = item['Status Hubungan dalam Keluarga'] || item['Hubungan'] || '';
          return {
            id: `imp-${Date.now()}-${index}`,
            dusun: item['Dusun'] || '-',
            rt: item['RT'] || '-',
            rw: item['RW'] || '-',
            noKK: (item['No.KK'] || item['No. KK'] || '').replace(/\D/g, '').slice(0, 16),
            nik: (item['NIK'] || '').replace(/\D/g, '').slice(0, 16),
            fullName: (item['Nama Lengkap'] || '-').toUpperCase(),
            relationship: rel,
            birthPlace: item['Tempat Lahir'] || '', 
            birthDate: item['Tanggal Lahir'] || item['Tgl Lahir'] || '1990-01-01',
            gender: (item['Jenis Kelamin'] || item['JK'] || '').includes('P') ? 'Perempuan' : 'Laki-laki',
            bloodType: (item['Golongan Darah'] || item['Gol. Darah'] || 'Tidak Tahu') as BloodType,
            maritalStatus: (item['Status Perkawinan'] || item['Status'] || 'Belum Kawin') as MaritalStatus,
            education: (item['Pendidikan Tertinggi'] || item['Pendidikan'] || 'SMA') as Education,
            job: item['Pekerjaan'] || '',
            fatherName: item['Nama Ayah Kandung'] || '',
            motherName: item['Nama Ibu Kandung'] || '',
            isHeadOfFamily: rel.toLowerCase().includes('kepala keluarga') || rel.startsWith('1'),
            status: 'Aktif' as ResidentStatus
          };
        });
        setResidents(prev => [...prev, ...newResidents]);
        setIsImporting(false);
        alert(`Berhasil mengimpor ${newResidents.length} data.`);
        if (fileInputRef.current) fileInputRef.current.value = '';
      } catch (err) {
        alert('Gagal impor.');
        setIsImporting(false);
      }
    };
    reader.readAsText(file);
  };

  const handleArchiveMove = (destination: string, date: string) => {
    if (!movingFamily) return;
    setResidents(prev => prev.map(r => 
      r.noKK === movingFamily.noKK ? {
        ...r, status: 'Pindah' as ResidentStatus, moveDestination: destination, moveDate: date
      } : r
    ));
    setMovingFamily(null);
  };

  return (
    <div className="space-y-3 md:space-y-6">
      {(isImporting || isPreparingPDF) && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl text-center">
             <Loader2 className="mx-auto text-blue-600 animate-spin mb-4" size={32} />
             <p className="text-xs font-black uppercase text-slate-950 dark:text-white">{isPreparingPDF ? "Cetak PDF..." : "Memproses..."}</p>
          </div>
        </div>
      )}

      {/* Action Bar (Mobile-Ultra-Compact) */}
      <div className="flex flex-col gap-2 bg-white dark:bg-slate-900 p-2.5 rounded-2xl md:rounded-[2.5rem] shadow-sm border border-slate-200 dark:border-slate-800 no-print">
        <div className="flex items-center bg-slate-100 dark:bg-slate-800 rounded-lg px-3 py-2 border border-slate-200 dark:border-slate-700 w-full">
          <Search size={14} className="text-slate-400 mr-2" />
          <input 
            type="text" 
            placeholder="Cari..."
            className="bg-transparent border-none outline-none text-[11px] w-full font-bold text-slate-950 dark:text-white"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex items-center overflow-x-auto gap-1 scrollbar-hide">
          <button onClick={() => setIsAddModalOpen(true)} className="flex items-center space-x-1 px-2.5 py-1.5 bg-slate-950 dark:bg-blue-600 text-white rounded-md text-[7px] font-black uppercase whitespace-nowrap">
            <Plus size={10} /> <span>Tambah</span>
          </button>
          <button onClick={handleDownloadPDF} className="flex items-center space-x-1 px-2.5 py-1.5 bg-rose-600 text-white rounded-md text-[7px] font-black uppercase whitespace-nowrap">
            <Printer size={10} /> <span>Cetak</span>
          </button>
          <button onClick={handleDownloadCSV} className="flex items-center space-x-1 px-2.5 py-1.5 bg-emerald-600 text-white rounded-md text-[7px] font-black uppercase whitespace-nowrap">
            <Download size={10} /> <span>CSV</span>
          </button>
          <label className="flex items-center space-x-1 px-2.5 py-1.5 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 border border-blue-200 rounded-md text-[7px] font-black uppercase whitespace-nowrap cursor-pointer">
            <Upload size={10} /> <span>Impor</span>
            <input ref={fileInputRef} type="file" className="hidden" onChange={handleImport} accept=".csv" />
          </label>
        </div>
      </div>

      {/* Filter Bar (Ultra Compact) */}
      <div className="bg-white dark:bg-slate-900 p-2 rounded-xl md:rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-x-auto scrollbar-hide">
        <div className="flex items-center space-x-2 min-w-max">
          <div className="flex items-center bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md px-1.5 py-1">
            <MapPin size={10} className="text-slate-400 mr-1" />
            <select className="bg-transparent text-[7px] font-black uppercase outline-none text-slate-950 dark:text-white" value={filters.dusun} onChange={(e) => setFilters({ ...filters, dusun: e.target.value, rw: '', rt: '' })}>
              <option value="">Dusun</option>
              {dusunList.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
          <div className="flex items-center bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md px-1.5 py-1">
            <span className="text-[6px] font-black text-slate-400 mr-1 uppercase">RW</span>
            <select className="bg-transparent text-[7px] font-black outline-none text-slate-950 dark:text-white" value={filters.rw} onChange={(e) => setFilters({ ...filters, rw: e.target.value, rt: '' })} disabled={!filters.dusun}>
              <option value="">-</option>
              {rwList.map(rw => <option key={rw} value={rw}>{rw}</option>)}
            </select>
          </div>
          <div className="flex items-center bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md px-1.5 py-1">
            <span className="text-[6px] font-black text-slate-400 mr-1 uppercase">RT</span>
            <select className="bg-transparent text-[7px] font-black outline-none text-slate-950 dark:text-white" value={filters.rt} onChange={(e) => setFilters({ ...filters, rt: e.target.value })} disabled={!filters.rw}>
              <option value="">-</option>
              {rtList.map(rt => <option key={rt} value={rt}>{rt}</option>)}
            </select>
          </div>
          <button onClick={() => setFilters({ dusun: '', rw: '', rt: '' })} className="p-1 text-slate-400"><RefreshCcw size={10} /></button>
          <div className="text-[7px] font-black text-slate-500 uppercase bg-slate-100 dark:bg-slate-800 px-1.5 py-1 rounded-md ml-auto">
            {filteredData.length} KK
          </div>
        </div>
      </div>

      {/* Mobile Card View (Ultra-Compact) */}
      <div className="grid grid-cols-1 md:hidden gap-3 no-print">
        {filteredData.length > 0 ? filteredData.map((r) => (
          <div key={r.id} className="bg-white dark:bg-slate-900 p-3 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm relative overflow-hidden group">
             <div className="absolute top-0 left-0 w-1 h-full bg-blue-600"></div>

             <div className="flex justify-between items-start mb-2">
                <div className="flex items-center space-x-2 min-w-0 flex-1">
                   <div className="w-8 h-8 bg-slate-100 dark:bg-slate-800 rounded-lg flex items-center justify-center text-slate-400 shrink-0">
                      <User size={16} />
                   </div>
                   <div className="min-w-0 flex-1">
                      <button 
                        onClick={() => setViewingFamilyKK(r.noKK)}
                        className="text-[11px] font-black uppercase text-slate-950 dark:text-white leading-tight truncate text-left w-full hover:text-blue-600"
                      >
                        {r.fullName}
                      </button>
                      <button 
                        onClick={() => setViewingFamilyKK(r.noKK)}
                        className="text-[9px] font-mono font-bold text-blue-600 dark:text-blue-400 mt-0.5 truncate block"
                      >
                        KK: {r.noKK}
                      </button>
                   </div>
                </div>
                <div className="flex items-center space-x-1 shrink-0 ml-1">
                   <button onClick={() => setViewingFamilyKK(r.noKK)} className="p-1.5 bg-blue-50 dark:bg-blue-900/30 text-blue-600 rounded-md"><Eye size={14} /></button>
                   <button onClick={() => setEditingResident(r)} className="p-1.5 bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-400 rounded-md"><Edit3 size={14} /></button>
                </div>
             </div>

             <div className="grid grid-cols-2 gap-2 border-t border-slate-100 dark:border-slate-800 pt-2 mb-2">
                <div className="min-w-0">
                   <p className="text-[6px] font-black text-slate-400 uppercase tracking-widest">Wilayah</p>
                   <p className="text-[9px] font-bold text-slate-900 dark:text-slate-300 uppercase truncate leading-none">{r.dusun}</p>
                   <p className="text-[8px] font-black text-slate-500 uppercase mt-0.5">RT {r.rt} / RW {r.rw}</p>
                </div>
                <div className="min-w-0">
                   <p className="text-[6px] font-black text-slate-400 uppercase tracking-widest">Identitas</p>
                   <p className="text-[9px] font-mono font-bold text-slate-900 dark:text-slate-300 truncate leading-none">{r.nik}</p>
                   <span className={`text-[6px] font-black uppercase px-1 py-0.5 rounded-md inline-block mt-1 ${r.gender.includes('Laki') ? 'bg-blue-100 text-blue-600' : 'bg-pink-100 text-pink-600'}`}>
                      {r.gender.includes('Laki') ? 'LAKI-LAKI' : 'PEREMPUAN'}
                   </span>
                </div>
             </div>

             <div className="flex items-center gap-1">
                <button onClick={() => setMovingFamily(r)} className="flex-1 py-1.5 bg-amber-50 dark:bg-amber-900/20 text-amber-600 dark:text-amber-400 rounded-lg text-[7px] font-black uppercase border border-amber-100 flex items-center justify-center space-x-1">
                   <PlaneLanding size={10} /> <span>Pindah</span>
                </button>
